window.REPORT_PRELOAD_CACHE["UAA.html"] = {"version":"bd3507b88349b22594f660ca5adec6b63c9af6e7cff44cb15b1259f3f0faf994","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>安德玛 Under Armour, Inc. Class A (NYSE: UAA) 深度商业与投资价值分析报告</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n uared: {\n 300: '#FCA5A5',\n 400: '#F87171',\n 500: '#DC2626',\n 600: '#B91C1C',\n 700: '#991B1B',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar { width: 6px; height: 6px; }\n ::-webkit-scrollbar-track { background: transparent; }\n ::-webkit-scrollbar-thumb { background: #94A3B8; border-radius: 3px; }\n .dark ::-webkit-scrollbar-thumb { background: #475569; }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print { display: none !important; }\n main { margin-left: 0 !important; padding: 0 !important; }\n section { break-inside: avoid; }\n }\n\n .report-card { transition: transform 0.2s ease, box-shadow 0.2s ease; }\n .report-card:hover { transform: translateY(-2px); }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(220, 38, 38, 0.22) 0%, rgba(16, 185, 129, 0.05) 100%);\n border-left: 3px solid #DC2626;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-uared-500 selection:text-white transition-colors duration-200\">\n\n <!-- 全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-uared-600 via-uared-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-uared-600 to-navy-900 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n UAA\n </div>\n <div>\n <div class=\"text-[11px] text-uared-300 font-semibold tracking-wider uppercase\">NYSE: UAA · Athletic Apparel</div>\n <div class=\"text-sm font-bold leading-tight\">安德玛-A 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 text-slate-300\" aria-label=\"主题切换\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 text-white\" aria-label=\"菜单\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">UAA 研报目录</span>\n <button onclick=\"toggleMobileMenu()\" class=\"text-slate-400 hover:text-white\">✕</button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">00. 执行摘要与最新财报</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">01. 商业模式与产品生态</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">02. 核心竞争优势与战略转型</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">03. 财务表现与 Q3 2026 业绩洞察</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">04. 同业竞争与市场格局</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">05. 估值展望与投资策略</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">06. 跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>美股运动服饰与品牌重塑研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 财报)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧边栏 (280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-uared-600 to-navy-900 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-uared-600/25\">\n UAA\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-uared-300 bg-uared-500/15 px-2 py-0.5 rounded\">NYSE: UAA</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">安德玛-A 深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球知名运动服饰与鞋履创新品牌 · 创始人 Kevin Plank 归来主导品牌重塑与精简 SKU 战略\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (Q4 2026)</span>\n <span class=\"font-mono font-bold text-white\">~$5.28 <span class=\"text-slate-400 text-[10px]\">($4.50-$8.20)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">第三季度净营收</span>\n <span class=\"font-mono font-bold text-emerald-400\">$12.4亿 (超预期)</span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">全年调整后 EPS 指引</span>\n <span class=\"font-mono font-bold text-uared-300\">~$0.10 (中位数)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">报告核心章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-uared-400 mr-2\">00</span>执行摘要与最新财报</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与产品生态</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>核心竞争优势与战略转型</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>财务表现与 Q3 2026 业绩洞察</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>同业竞争与市场格局</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>估值展望与投资策略</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">页面显示模式</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-uared-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-uared-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色模式</span>\n <span class=\"hidden dark:inline\">浅色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-uared-600 to-uared-700 hover:from-uared-700 text-white text-xs font-extrabold transition cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span class=\"text-white\">打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. 封面与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-uared-500/15 text-uared-700 dark:text-uared-300 font-bold border border-uared-500/30\">机构评级：持有 / 战略转型观察</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">覆盖基准：2026年最新季度财报与重塑战略</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>股票代码：NYSE: UAA</span>\n <span>总市值：~$22.3 亿</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#DC2626 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-uared-500/20 border border-uared-400/40 text-uared-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-uared-400 animate-pulse\"></span>\n <span>EXECUTIVE SUMMARY · Q3 营收超预期达 $12.4亿 × 调整后 EPS 符合预期 ($0.00) × 创始人 Kevin Plank 推进精简 SKU 与核心特许经营重塑</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 安德玛-A Under Armour, Inc. Class A (NYSE: UAA) 深度商业与投资价值分析报告\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 安德玛（Under Armour, Inc., 代码：<strong class=\"text-white\">UAA</strong>）作为全球知名的功能性运动服饰与鞋履创新先驱，当前正处于创始人兼 CEO Kevin Plank 领导下的深度战略重塑期 [cite: 1.1.1]。在最新发布的 <strong class=\"text-uared-300\">2026财年第三季度财报</strong>中，公司营收达到 <strong class=\"text-white\">$12.4亿美元</strong>（超越市场一致预期的 $12.3亿），调整后每股收益（EPS）为 <strong class=\"text-emerald-400\">$0.00</strong>（符合预期） [cite: 1.1.1]。\n 面对北美市场消费者客流疲软与高度促销的零售环境，公司正通过精简产品线（SKU）、聚焦 HeatGear 与 Vanish 等核心王牌特许经营系列、以及优化库存与资产轻量化模式，全力修复品牌溢价与盈利能力 [cite: 1.1.1]。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 营收小幅超预期</div>\n <div class=\"text-white font-semibold\">净营收达 $12.4 亿（同比下降 6.9%，但微幅战胜市场一致预期），调整后 EPS 达成 $0.00 [cite: 1.1.1]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">核心系列与精简战略</div>\n <div class=\"text-uared-300 font-semibold\">创始人 Kevin Plank 领导简化产品矩阵，集中资源发力 HeatGear 与 Vanish 核心特许经营系列 [cite: 1.1.1]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">纪律性库存与费用管控</div>\n <div class=\"text-emerald-400 font-semibold\">库存水平持续优化（同比下降 2% 左右），坚持严格的 SG&A 费用纪律以应对宏观阻力 [cite: 1.1.1, 1.1.2]</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 四大核心 KPI 指标卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 净营收</span>\n <span class=\"p-1.5 rounded-lg bg-uared-500/15 text-uared-600 dark:text-uared-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$12.4亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">微幅超预期</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 第三季度营收实现 12.4 亿美元，超出 S&P 分析师共识预期（$12.3亿），表现出一定韧性 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>调整后每股收益 (EPS)</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$0.00</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">符合预期</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 非 GAAP 调整后 EPS 录得 $0.00，完美符合市场一致预期，盈利表现处于巩固筑底期 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>调整后营业利润</span>\n <span class=\"p-1.5 rounded-lg bg-uared-500/15 text-uared-600 dark:text-uared-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$2,490万</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">大超预期 80%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后营业利润达到 2494 万美元（运营利润率 1.2%），大幅超越市场预期的 1383 万美元 [cite: 1.1.1, 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>全渠道库存状况</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">健康可控</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">持续降库优化</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 供应链与库存管理保持高度纪律性，库存同比保持压降状态，有效缓解促销带来的毛利侵蚀 [cite: 1.1.1, 1.1.2]。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与产品生态\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uared-600 dark:text-uared-400\">Section 01 · Business Model & Product Ecosystem</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与产品生态：功能性运动服饰创新与全渠道分销</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">产品大类：服装、鞋履与配件 · 批发与直销 (DTC) 双轨驱动</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">安德玛产品类别与销售渠道占比估算 (%)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">专业运动服装、鞋履、配件及批发与直营（DTC）全景矩阵</p>\n </div>\n <span class=\"px-2.5 py-1 rounded bg-uared-500/15 text-uared-600 dark:text-uared-400 text-xs font-bold\">专业运动装备领先者</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizSegmentChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业模式三大核心支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-uared-500/15 text-uared-600 dark:text-uared-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">功能性服装与核心特许经营 (Core Franchises)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 以 HeatGear、ColdGear 和 Vanish 等标志性面料科技为核心，为全球运动员和健身爱好者提供高性能吸湿排汗运动服装，占总营收近七成。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-slate-200 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">鞋履与配件创新</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 不断发力专业跑步鞋、篮球鞋及训练鞋市场，通过科技迭代提升鞋履板块的毛利率与市场渗透率。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">全渠道分销 (批发 + 直销 DTC + 资产轻量化授权)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 结合全球体育用品批发商网络、自有零售店与电商平台（DTC），并积极探索青少年服装等领域的资产轻量化特许经营授权模式 [cite: 1.1.1]。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心战略转向</span>\n <span class=\"font-bold text-uared-600 dark:text-uared-400\">精简 SKU，聚焦高胜率核心产品线</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 核心竞争优势与战略转型\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Competitive Advantages & Transformation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 核心竞争优势与战略转型：创始人回归、产品简化与精细化运营</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">转型评级：品牌重塑期 (Brand Turnaround)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-uared-500/15 text-uared-600 dark:text-uared-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">创始人 Kevin Plank 强势回归掌舵</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 创始人重新担任 CEO，展现出强烈的变革决心与对品牌基因的深刻理解，集中精锐资源聚焦最具胜率的细分领域 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">精简产品矩阵与 SKU 优化</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 大力削减冗余产品线，大幅降低 SKU 数量，将行销与研发资源集中于 HeatGear、Vanish 等核心特许经营系列，显著提升供应链效率 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-blue-500/15 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">资产轻量化与特许经营授权模式</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过特许经营授权（如青少年服装等领域）优化运营模式，减轻重资产包袱，改善整体现金流与资本回报率 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">严格的费用与库存纪律</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 面对零售促销环境，坚持严格的销售、一般及行政费用（SG&A）管控与库存清理，为未来毛利率修复奠定坚实基础 [cite: 1.1.1, 1.1.2]。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">运动服饰行业五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">UAA vs 行业平均水平综合评分（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 财务表现与 Q3 2026 业绩洞察\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uared-600 dark:text-uared-400\">Section 03 · Financial Performance & Q3 2026 Earnings</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 财务表现与 Q3 2026 业绩洞察：营收超预期与利润筑底</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 营收 $12.4亿 · 调整后营业利润 $2490万 [cite: 1.1.1]</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-uared-600 dark:text-uared-400 uppercase\">Q3 Net Revenue</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$12.4亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 第三季度净营收达 12.4 亿美元（同比下降 6.9%，但优于市场普遍预期的 12.3 亿美元） [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Adjusted Operating Income</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$2,490万</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 调整后营业利润达 2,490 万美元，大幅超越分析师预期的 1,383 万美元（运营利润率 1.2%） [cite: 1.1.1, 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-uared-600 dark:text-uared-400 uppercase\">Adjusted EPS</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$0.00</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 非 GAAP 调整后 EPS 录得 $0.00，符合市场一致预期，显示出公司在转型期对盈利底线的坚守 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">FY2026 EPS Guidance</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$0.10</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 管理层重申全年调整后 EPS 指引中位数为 $0.10，反映出对外部宏观成本与库存调控的持续把控 [cite: 1.1.4, 1.2.4]。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">安德玛近年营业收入与盈利趋势 ($ 亿美元)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">营收受北美客流与转型期 SKU 精简影响承压，盈利端正通过成本纪律稳步筑底</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-uared-700 dark:text-uared-300 bg-uared-500/15 px-2.5 py-1 rounded\">战略重塑期</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"finTrendChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 同业竞争与市场格局\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uared-600 dark:text-uared-400\">Section 04 · Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 同业竞争与市场格局：Nike 与 Lululemon 领跑，UAA 聚焦专业运动利基</h2>\n </div>\n <div class=\"flex items-center space-x-2 text-xs text-slate-500 dark:text-slate-400\">\n <span>对标同业：Nike, Lululemon, Adidas, On Running</span>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">公司名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">行业地位</th>\n <th class=\"py-4 px-4 min-w-[140px]\">市值/规模特点</th>\n <th class=\"py-4 px-4 min-w-[120px]\">核心主营业务</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心竞争优势与当前挑战</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\">\n <tr class=\"bg-uared-500/5 dark:bg-uared-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-uared-700 text-white text-[10px] font-extrabold\">本文主角</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">Under Armour (NYSE: UAA)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">专业运动创新品牌</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">中坚挑战者</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~$22.3 亿 [cite: 1.1.1]</td>\n <td class=\"py-4 px-4 text-emerald-600 dark:text-emerald-400 font-semibold\">功能性服装与鞋履</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>重塑与精简：</strong>创始人回归推进 SKU 精简与核心特许经营升级，正处于业绩筑底与盈利修复关键期 [cite: 1.1.1]。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Nike, Inc. (NYSE: NKE)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球运动服饰绝对龙头</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">行业绝对巨头</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">千亿级大市值</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球鞋履与运动服饰</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球品牌壁垒：</strong>拥有顶级球星代言矩阵与极强的全球供应链壁垒，但也面临创新放缓的周期挑战。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Lululemon Athletica (NASDAQ: LULU)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">高端运动休闲引领者</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高端细分龙头</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高估值高毛利</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高端瑜伽与运动休闲</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>社群与高毛利：</strong>凭借面料创新与强大社群营销，保持行业领先的毛利率与消费者粘性。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 估值展望与投资策略\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-uared-600 dark:text-uared-400\">Section 05 · Valuation Outlook & Investment Strategy</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 估值展望与投资策略：转型期保持耐心，静待品牌重塑成效</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">目标价区间：$5.50 – $7.50（机构共识观察期）</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">目标价：$8.00 – $10.00+</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">重塑计划超预期兑现</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>Kevin Plank 领导的产品精简与核心特许经营升级大获成功，毛利率显著回升，全渠道 DTC 销售重回增长轨道。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 转型成功带来的估值修复弹性\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-uared-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-uared-500/15 text-uared-700 dark:text-uared-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-uared-600 dark:text-uared-400\">目标价：$5.50 – $6.50</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">业绩筑底与稳步转型</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>公司达成全年调整后 EPS $0.10 的指引，库存保持健康，但受制于宏观零售竞争，营收增速呈弱复苏态势 [cite: 1.1.4]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-uared-600 dark:text-uared-400\">\n 当前股价区间震荡，等待长期拐点\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">谨慎情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">目标价：$3.50 – $4.50</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">北美零售客流持续低迷</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>若北美消费者需求进一步疲软，促销力度加大导致毛利率受损，转型周期被拉长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 需警惕鞋履与北美批发渠道的持续回调风险\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-uared-300 mb-3 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构投资策略建议</span>\n </h3>\n <p class=\"text-xs sm:text-sm text-slate-300 leading-relaxed\">\n 安德玛-A (UAA) 目前正处于创始人 Kevin Plank 领导的深水区转型期。虽然三季度营收与营业利润展现出超预期的韧性，但整体营收仍在经历调整。对于长线投资者，当前低股价反映了大部分悲观预期，建议保持观察或逢低建仓，重点跟踪后续核心产品系列的市场反馈与毛利率修复情况。\n </p>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 跟踪 KPI 核查清单\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Regular Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 定期跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-uared-500/15 text-uared-700 dark:text-uared-300 text-xs font-bold\">已核查 3 / 5 项 (60%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选 UAA 投资组合监控中的关键运营指标（本地状态自动保存）：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#DC2626]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. SKU 精简与核心特许经营系列（HeatGear/Vanish）销售占比提升</span>\n <span class=\"text-[11px] font-mono text-uared-600 dark:text-uared-400 font-semibold shrink-0\">产品重塑指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控产品矩阵精简成效，确保核心王牌产品获得消费者青睐并支撑毛利率 [cite: 1.1.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#DC2626]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 库存水平保持健康压降，避免过度促销侵蚀毛利</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">供应链健康度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认全渠道库存持续同比压降，维持良好的供应链健康与定价权 [cite: 1.1.1, 1.1.2]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#DC2626]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 全年调整后 EPS 指引顺利兑现（中位数 ~$0.10）</span>\n <span class=\"text-[11px] font-mono text-uared-600 dark:text-uared-400 font-semibold shrink-0\">盈利达成度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核查每季度财报盈利表现是否符合或超越管理层给出的年度指引 [cite: 1.1.4]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#DC2626]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 销售、一般及行政费用（SG&A）保持严格纪律性管控</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">费用控制指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确保管理层在营销与运营开支上保持紧缩与高效，抵御宏观需求波动 [cite: 1.1.1, 1.1.2]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#DC2626]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 北美市场客流回暖与国际市场（EMEA/拉美）持续扩张</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">区域增长动能</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪北美本土销售企稳情况及国际新兴市场的增长势头 [cite: 1.1.1, 1.1.2]。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>安德玛-A Under Armour, Inc. Class A (NYSE: UAA) 深度商业与投资价值分析报告 [cite: 1.1.1]</span>\n <span>数据基准：2026 年 Q3 财报与公开资本市场披露 [cite: 1.1.1]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本报告基于 Under Armour 公开披露的财务财报、SEC 申报文件及市场分析数据撰写，旨在提供结构化商业研究参考。报告中的前瞻性预测、目标价及财务推演不构成任何直接证券投资建议。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-uared-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-uared-400');\n }\n }\n });\n });\n\n const KPI_STORAGE_KEY = 'uaa_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizSegmentChartInstance = null;\n let moatRadarChartInstance = null;\n let finTrendChartInstance = null;\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizSegmentChart() {\n const ctx = document.getElementById('bizSegmentChart').getContext('2d');\n const colors = getChartColors();\n\n if (bizSegmentChartInstance) bizSegmentChartInstance.destroy();\n bizSegmentChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['服装产品 (Apparel)', '鞋履产品 (Footwear)', '配件产品 (Accessories)', '批发渠道 (Wholesale)', '直销渠道 (DTC)'],\n datasets: [\n {\n label: '业务板块销售占比估算 (%)',\n data: [68, 22, 10, 52, 48],\n backgroundColor: '#DC2626',\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `占比约: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 80,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initMoatRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (moatRadarChartInstance) moatRadarChartInstance.destroy();\n moatRadarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '创始人回归与战略重塑执行力',\n '核心面料科技与功能性服装心智',\n '精简 SKU 与供应链库存纪律',\n '全球全渠道分销网络 (批发+DTC)',\n '资产轻量化授权与费用管控'\n ],\n datasets: [\n {\n label: 'UAA (安德玛-A)',\n data: [9.0, 9.2, 8.8, 8.5, 8.7],\n borderColor: '#DC2626',\n backgroundColor: 'rgba(220, 38, 38, 0.22)',\n pointBackgroundColor: '#DC2626',\n borderWidth: 2.5\n },\n {\n label: '行业平均水平',\n data: [7.5, 8.0, 7.8, 8.2, 7.8],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.12)',\n pointBackgroundColor: '#10B981',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initFinTrendChart() {\n const ctx = document.getElementById('finTrendChart').getContext('2d');\n const colors = getChartColors();\n\n if (finTrendChartInstance) finTrendChartInstance.destroy();\n finTrendChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026 (F)'],\n datasets: [\n {\n type: 'bar',\n label: '全年净营收 Net Revenue ($ 亿)',\n data: [59.0, 57.0, 51.6, 49.5],\n backgroundColor: 'rgba(220, 38, 38, 0.85)',\n borderRadius: 6,\n barThickness: 32,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后营业利润 Adjusted Operating Income ($ 亿)',\n data: [4.8, 3.9, 2.8, 3.2],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 70,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + '亿' },\n title: { display: true, text: '净营收 ($亿)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 10,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + '亿' },\n title: { display: true, text: '调整后营业利润 ($亿)', color: '#10B981', font: { size: 11 } }\n },\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n });\n </script>\n</body>\n</html>\n"};
